def _feedback_from_review_findings_process(f) -> tuple[str, str] | None:
    """Process a single review finding; return (tid, block) or None if skipped."""
    if getattr(f, 'severity', None) != 'blocker':
        return None
    tid = getattr(f, 'task_id', None)
    if not tid:
        return None
    parts = [f"- [{getattr(f, 'severity', 'blocker')}] {getattr(f, 'message', '')}"]
    if getattr(f, 'file', None):
        parts.append(f'  file: {f.file}')
    if getattr(f, 'line', None) is not None:
        parts.append(f'  line: {f.line}')
    if getattr(f, 'suggestion', None):
        parts.append(f'  fix: {f.suggestion}')
    return (tid, '\n'.join(parts))


def _feedback_from_review_findings_apply_traceback(out: dict[str, list[str]], traceback_route: str) -> None:
    """Append reviewer note to all existing feedback blocks."""
    for tid, lines in out.items():
        lines.append(f'  reviewer note: {traceback_route}')"}
